// What the OBS dock talks to: the secret address, the data the page reads, and the few things it can ask for (replay, pause, resume, empty, test).
// The address is a secret like the one of the raid docks: `?k=…`, compared in constant time, regenerated by "New address" (the old docks stop at once). No session of the administration is needed in OBS.
// Only display names, amounts and counts leave this file: never a token, a secret or an e-mail.
import { randomBytes, createHash, timingSafeEqual } from "node:crypto";
const v = new URL(import.meta.url).search; // the version of the module spreads to the neighbour files (otherwise the old code would stay cached after an update)
const es = await import(`./eventsub.mjs${v}`);
const st = await import(`./state.mjs${v}`);
const pub = await import(`./publish.mjs${v}`);
const admin = await import(`./describe.mjs${v}`);

export const SERVICE = "alerts.queue";
export const LIMITS = { dataPerMinute: 90, actPerMinute: 40, badPerMinute: 30, events: 200, scopes: ["stream", "day", "all"] };
const day = 86_400_000;

/* ───────────── The secret address ───────────── */
const newSecret = () => randomBytes(24).toString("base64url");
export async function dockSecret(ctx) {
  const s = await st.readState(ctx);
  if (s.dockSecret) return s.dockSecret;
  const secret = newSecret();
  await st.updateState(ctx, (d) => { d.dockSecret ??= secret; });
  return (await st.readState(ctx)).dockSecret;
}
/** A new address: the old one stops working at once. */
export async function renewDockSecret(ctx) {
  const secret = newSecret();
  await st.updateState(ctx, (d) => { d.dockSecret = secret; });
  return secret;
}
export const dockUrl = (ctx, secret) => `${String(ctx.api.siteUrl ?? "").replace(/\/+$/, "")}/m/${ctx.instance.key}/dock?k=${encodeURIComponent(secret)}`;
/** Is the given secret the right one? Constant time on fixed-length digests; creates nothing; too many wrong tries in a minute are refused before any comparison. */
export async function secretMatches(ctx, given, { now = Date.now() } = {}) {
  const m = st.memoryOf(ctx);
  m.dockBad = (m.dockBad ?? []).filter((t) => now - t < 60_000);
  if (m.dockBad.length >= LIMITS.badPerMinute) return { ok: false, limited: true };
  const s = await st.readState(ctx);
  const ok = typeof given === "string" && given.length > 0 && given.length <= 200 && !!s.dockSecret
    && timingSafeEqual(createHash("sha256").update(s.dockSecret).digest(), createHash("sha256").update(given).digest());
  if (!ok) m.dockBad.push(now);
  return { ok };
}
export const keyOf = (request) => { try { return new URL(request.url).searchParams.get("k") ?? ""; } catch { return ""; } };

/* ───────────── The alerts overlay, if there is one ───────────── */
/** One answer of the queue service of the alerts overlays, or null: { linked, paused, held }. `call` = pause | resume | clear | state. */
export async function queue(ctx, call = "state") {
  let list = [];
  try { list = await ctx.api.instances.list({ module: "alerts-overlay" }); } catch { list = []; }
  const linked = Array.isArray(list) && list.some((i) => i?.module === "alerts-overlay");
  if (!linked) return { linked: false, paused: false, held: 0 };
  let answers = [];
  try { answers = await ctx.api.services.callAll(SERVICE, call, {}); } catch { answers = []; }
  const ok = (Array.isArray(answers) ? answers : []).filter((a) => a?.ok && a.value && typeof a.value === "object");
  return { linked: true, reachable: ok.length > 0, paused: ok.some((a) => a.value.paused === true), held: ok.reduce((n, a) => n + (Number(a.value.held) || 0), 0), dropped: ok.reduce((n, a) => n + (Number(a.value.dropped) || 0), 0), released: ok.reduce((n, a) => n + (Number(a.value.released) || 0), 0) };
}

/* ───────────── What the page reads ───────────── */
/** `scope`: "stream" (since the stream started, when we know it), "day" (24 h) or "all" (what the journal keeps). */
export async function payload(ctx, { scope = "day", now = Date.now() } = {}) {
  const t = ctx.t, state = await st.readState(ctx);
  const sc = LIMITS.scopes.includes(scope) ? scope : "day";
  const live = typeof state.liveSince === "number" && state.liveSince > 0;
  const cut = sc === "stream" ? (live ? state.liveSince : now - day) : sc === "day" ? now - day : 0;
  const lines = (await st.recent(ctx, 400)).filter((l) => l.at >= cut).slice(0, LIMITS.events);
  const q = await queue(ctx);
  return {
    now, scope: sc, live, liveSince: live ? state.liveSince : null, listening: state.listen?.code === "listening",
    events: lines.map((l) => ({ id: l.id, kind: l.kind, label: t(`kind_${l.kind}`), tone: admin.TONE[l.kind] ?? "neutral", name: admin.who(ctx, l), detail: admin.detail(ctx, l), at: l.at, test: l.source === "test", replay: l.source === "replay" })),
    alerts: { linked: q.linked, paused: q.paused, held: q.held },
    types: es.TYPES.map((x) => ({ id: x.id, name: t(`type_${x.id}`) })),
  };
}

/* ───────────── What the page can ask ───────────── */
/** { ok: true, … } or { ok: false, code: "rate" | "unknown" | "no_alerts" | "bad" }. */
export async function act(ctx, body, { now = Date.now() } = {}) {
  if (!st.allow(ctx, "dockAct", { max: LIMITS.actPerMinute, windowMs: 60_000, now })) return { ok: false, code: "rate" };
  const a = String(body?.action ?? "");
  if (a === "replay") {
    const q = await queue(ctx, "state");
    if (!q.linked) return { ok: false, code: "no_alerts" };
    const r = await pub.replay(ctx, String(body?.id ?? ""), { now });
    return r.ok ? { ok: true, again: r.again === true } : { ok: false, code: r.code };
  }
  if (a === "test") {
    const q = await queue(ctx, "state");
    if (!q.linked) return { ok: false, code: "no_alerts" };
    const r = await pub.sendTest(ctx, String(body?.type ?? ""), { now });
    return r.ok ? { ok: true } : { ok: false, code: r.code };
  }
  if (a === "pause" || a === "resume" || a === "clear") {
    const q = await queue(ctx, a);
    if (!q.linked) return { ok: false, code: "no_alerts" };
    return { ok: true, paused: a === "pause" ? true : a === "resume" ? false : q.paused, held: q.held, released: q.released, dropped: q.dropped };
  }
  return { ok: false, code: "bad" };
}
